def encrypt(s):
    result = ""
    for char in s:
        if char.isalpha():
            shift = 2 * ord(char) - ord('a')
            if char.islower():
                result += chr((shift % 26) + ord('a'))
            else:
                result += chr((shift % 26) + ord('A'))
        else:
            result += char
    return result

